return ['domain'=>'fancybox-for-wordpress','plural-forms'=>NULL,'language'=>'ja','project-id-version'=>'FancyBox for WordPress 3.4.0','pot-creation-date'=>'2026-08-06T12:05:16+00:00','po-revision-date'=>'','messages'=>['Save Changes'=>'設定保存','Settings'=>'設定','Zoom Options'=>'ズーム設定','Change content transparency during zoom animations (default: on)'=>'切替時、アニメーション動作を使用 (初期値: on)','Appearance Settings <span style="color:green">(basic)</span>'=>'外観設定 <span style="color:green">(基本設定)</span>','HTML color of the border (default: #BBBBBB)'=>'境界線の表示色 (初期値: #BBBBBB)','Padding'=>'パディング設定','HTML color of the padding (default: #FFFFFF)'=>'パッディングの表示色 (初期値: #FFFFFF)','Padding size in pixels (default: 10)'=>'パッディングサイズ：px (初期値: 10)','Overlay Options'=>'オーバレイ設定','Add overlay (default: on)'=>'オーバーレイ適用 (初期値: on)','HTML color of the overlay (default: #666666)'=>'オーバーレイの表示色 (初期値: #666666)','Opacity of overlay. 0 is transparent, 1 is opaque (default: 0.3)'=>'オーバーレイ透過度. 0 = 透明, 1 = 黒  0.1刻み(初期値: 0.3)','Behavior Settings <span style="color:orange">(medium)</span>'=>'動作設定 <span style="color:orange">(中間値)</span>','Close FancyBox by clicking on the image (default: off)'=>'FancyBoxをプレビュー画像クリックで閉じる。 (初期値: off)','Gallery Settings <span style="color:red">(advanced)</span>'=>'ギャラリー設定 <span style="color:red">(高度設定)</span>','Here you can choose if you want the plugin to group all images into a gallery, or make a gallery for each post. You can also define you own jQuery expression if you like.'=>'この設定で、すべての画像をギャラリーに分類するか、各ポストのためにギャラリーを作るかを選択できます。 また、jQueryの動作表現を定義できます。','Gallery Type'=>'ギャラリータイプ','Make a gallery for all images on the page (default)'=>'ページ上の全画像のためにギャラリーを作る (初期値)','Make a gallery for each post (will only work if your theme uses <code>class="post"</code> on each post, which is common in WordPress'=>'各ポストのためにギャラリーを作る (WordPress標準テーマにおいて<code>class="post"</code>を各ポストで使う場合に動作します。)','Use a custom expression to apply FancyBox'=>'FancyBoxへのカスタム表示の適用','Custom expression guidelines:'=>'カスタム表示ガイドライン：','Troubleshooting Settings'=>'トラブルシューティング設定','Settings in this section should only be changed if you are having problems with the plugin!'=>'プラグインに関する問題がある場合、この設定を変えるだけです!','If the plugin doesn\'t seem to work, first you should check for other plugins that may be conflicting with this one, especially other Lightbox, Slimbox, etc. Make sure all your plugins and WordPress itself are up to date (this plugin has only been tested in WordPress 2.7 and above).'=>'プラグインが機能しない場合は、はじめに他の類似プラグイン（特に他のLightbox、Slimbox）や、その他のプラグインと干渉している可能性があります。また、WordPress自体が最新版であることをチェックしてください。（このプラグインは、WordPress 2.7以上のバージョンでテスト済みです。）','Change them one at a time and test to see if they help. Remember that having a cache plugin may prevent changes from taking effect immidiately, so clear cache after saving changes here or deactivate cache until you finish editing these options.'=>'これらを一つずつを変更して、影響しているかどうかをテストしてください。これらのオプションを編集し終わってもキャッシュが保持されているため、オプション設定後、すぐに効果が表れないかもしれません。その場合、オプション設定終了後に、キャッシュのクリアをしてください。','Do not call jQuery'=>'jQueryを使用しない','Skip jQuery call. Use this only if jQuery is being loaded twice (default: off)'=>'jQueryの起動スキップ。jQueryが2度起動される場合だけ使用 (初期値: off)','Uninstall'=>'削除','Like many other plugins, FancyBox for WordPress stores its settings on your WordPress\' options database table. Actually, these settings are not using more than a couple of kilobytes of space, but if you want to completely uninstall this plugin, check the option below, then save changes, and <strong>when you deactivate the plugin</strong>, all its settings will be removed from the database.'=>'他のプラグインのように、"FancyBox for WordPress"は、データベースのオプションテーブルに設定を格納します。これらの設定は2KB以上のスペースを使っていません。しかし、<strong>このプラグインを無効化</strong>し、削除する場合、完全に元に戻したいならば、下記のオプションをチェックすると、すべての設定はデータベースから削除されます。','Remove settings'=>'設定の無効化','Remove Settings when plugin is deactivated from the "Manage Plugins" page. (default: off)'=>'プラグイン設定を "プラグイン管理"ページから無効化してください。 (初期値: off)']];